 const cityCovers={};if(raw.cityCovers!=null){if(typeof raw.cityCovers!=='object'||Array.isArray(raw.cityCovers))throw new Error('Copertine non valide.');for(const [key,value] of Object.entries(raw.cityCovers)){if(!['tokyo','kyoto','kanazawa','takayama','fuji','kamakura','shirakawago','kamikochi'].includes(key))throw new Error('Città della copertina non valida.');if(typeof value!=='string'||value.length>140000||!coverSource(value))throw new Error('La foto deve essere un’immagine caricata oppure un indirizzo https:// valido.');cityCovers[key]=value;}}
