function bookingsHTML(){const rows=model.reservations.filter(b=>(filter==='all'||(filter==='booked'?b.status==='booked':b.status!=='booked'))&&`${b.title} ${b.notes} ${b.type}`.toLowerCase().includes(query.toLowerCase()));return `<div class="page-heading"><div class="heading-row"><h1>Prenotazioni</h1>${editing?'<button class="primary" data-action="add-booking">＋ Aggiungi</button>':''}</div><p>${model.reservations.filter(b=>b.status==='booked').length} confermate · ${model.reservations.filter(b=>b.status!=='booked').length} da organizzare</p></div><div class="booking-tools"><div class="segmented" role="group" aria-label="Filtra prenotazioni">${[['all','Tutte'],['pending','Da organizzare'],['booked','Prenotate']].map(([f,t])=>`<button data-action="filter" data-filter="${f}" class="${filter===f?'active':''}" aria-pressed="${filter===f}">${t}</button>`).join('')}</div><input class="search-field" id="booking-search" aria-label="Cerca prenotazioni" placeholder="Cerca una prenotazione…" value="${esc(query)}"></div><div class="booking-grid">${rows.length?rows.map(bookingHTML).join(''):'<div class="empty">Nessuna prenotazione corrisponde alla ricerca.</div>'}</div>`}
function budgetHTML(){const total=model.budget.reduce((s,b)=>s+b.amount,0);return `<div class="page-heading"><h1>Budget del viaggio</h1><p>La previsione a persona, dal tuo programma.</p></div><div class="cost-total"><div><small>Totale previsto a persona</small><strong>${money(total)}</strong></div><p>Include volo, alloggi, attività, pasti e trasporti. Le quote delle prenotazioni sono riportate separatamente.</p></div><div class="budget-list">${model.budget.map(b=>`<div class="budget-item"><div><strong>${esc(b.label)}</strong><small>${total?(b.amount/total*100).toFixed(1).replace('.',','):0}% del budget</small><div class="bar" aria-hidden="true"><span style="width:${total?Math.min(100,b.amount/total*100):0}%"></span></div></div><div class="budget-amount">${money(b.amount)}${editing?`<button data-action="edit-budget" data-id="${esc(b.id)}">Modifica</button>`:''}</div></div>`).join('')}</div><p class="section-note">Il budget è una previsione, non il totale delle spese pagate. Modificare una prenotazione non cambia automaticamente queste categorie: puoi aggiornare qui la previsione.</p>${model.warnings.filter(w=>w.id==='w5').map(w=>`<div class="notice"><div><strong>Importo da verificare.</strong> ${esc(w.text)}</div></div>`).join('')}`}
function baseInfoHTML(){const i=model.info;return `<div class="page-heading"><h1>Info utili</h1><p>Le cose da tenere a portata di mano.</p></div><div class="info-grid"><section class="info-card"><h2>I nostri voli</h2><p>${esc(i.outbound)}</p><p>${esc(i.returnFlight)}</p><p>Gli orari sono quelli del foglio e si riferiscono all’ora locale indicata nella prenotazione. Verifica le differenze segnalate nel programma.</p></section><section class="info-card"><h2>Prima della partenza</h2><p>${esc(i.customs)}</p>${link(i.customsUrl,'Apri Visit Japan Web')}<p>${esc(i.esim)}</p>${link(i.esimUrl,'Vedi la eSIM')}</section><section class="info-card"><h2>Yen in euro</h2><label for="yen-amount" class="section-note">Importo in yen</label><div class="converter"><input id="yen-amount" type="number" min="0" step="1" value="1000" aria-label="Importo in yen"><span>¥ ≈</span><strong id="converted">${money(1000*i.exchange)}</strong></div><p class="section-note">Cambio di riferimento dal foglio: 1 ¥ = ${String(i.exchange).replace('.',',')} €. È una stima, non un cambio aggiornato.</p></section><section class="info-card"><h2>Note del viaggio</h2><p>${esc(i.notes||'Qui puoi aggiungere indirizzi, consigli e promemoria utili per il gruppo.')}</p>${editing?'<button class="secondary" data-action="edit-info">Modifica informazioni</button>':''}</section><section class="info-card wide"><h2>Il programma è tuo</h2><p>Premi Modifica per aggiungere un’attività, cambiare un orario o spostarla in un’altra giornata. Le modifiche vengono salvate nel browser di questo dispositivo.</p><p>Per usare le stesse modifiche su un altro telefono o PC, esporta una copia e importala sull’altro dispositivo. Il foglio Google rimane la fonte iniziale: non viene modificato dall’app.</p><div class="info-actions"><button class="primary" data-action="export">Esporta programma</button><button class="secondary" data-action="import">Importa programma</button></div>${link(model.sourceUrl,'Apri il foglio originale','source-link')}<p>Quando l’app sarà online, su iPhone aprila in Safari, premi Condividi e scegli Aggiungi alla schermata Home. Dopo la prima apertura online, programma e modifiche sono disponibili anche offline; mappe e siti esterni richiedono una connessione.</p></section></div>`}
function render(){selected=Math.max(0,Math.min(selected,model.days.length-1));main.className='view-'+view;main.innerHTML=(editing?'<div class="editing-banner">Modifica attiva · Ogni cambiamento viene salvato su questo dispositivo.</div>':'')+({program:programHTML,bookings:bookingsHTML,budget:budgetHTML,info:infoHTML,phrases:window.JAPAN_PHRASES.render}[view])();document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});document.querySelector('#pending-count').textContent=model.reservations.filter(b=>b.status!=='booked').length;document.querySelector('#edit-toggle').textContent=editing?'Fine modifica':'Modifica';document.querySelector('#edit-toggle').setAttribute('aria-pressed',editing);if(model.updatedAt)document.querySelector('#footer-date').textContent='Ultima modifica: '+new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short'}).format(new Date(model.updatedAt));}
function field(name,title,value,options={}){const type=options.type||'text',wide=options.wide?' wide':'';let control;if(type==='textarea')control=`<textarea id="f-${name}" name="${name}" rows="${options.rows||3}" maxlength="8000" ${name==='notes'?'data-note-editor':''}>${esc(value)}</textarea>`;else if(type==='select')control=`<select id="f-${name}" name="${name}">${options.choices.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;else control=`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${options.required?'required':''} ${type==='number'?'min="0" max="1000000" step="'+(options.step||'.01')+'"':''} ${type==='text'?'maxlength="4000"':''}>`;return `<div class="field${wide}"><label for="f-${name}">${title}</label>${control}${type==='textarea'&&name==='notes'?window.JAPAN_NOTES.fieldMarkup(name,value||'',options.format):''}${options.help?`<small>${options.help}</small>`:''}</div>`}
