function coverSource(value){if(typeof value!=='string')return '';if(/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(value))return value;if(value.length>2048)return '';try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password?url.href:''}catch{return ''}}
function kindValue(value){const text=String(value||'').trim(),known={attività:'attivita',attivita:'attivita','da vedere e da fare':'attivita',trasporto:'trasporto',spostamento:'trasporto',pasto:'pasto','a tavola':'pasto',nota:'nota','nota pratica':'nota'};return Object.hasOwn(known,text.toLowerCase())?known[text.toLowerCase()]:text}
