function previewCover(source){const preview=document.querySelector('#cover-preview');if(!preview)return;const day=model.days[selected],art=cityArt(day);preview.innerHTML=source?'<div class="cover-upload-preview"><img src="'+esc(source)+'" alt="Anteprima foto di '+esc(art.name)+'"></div>':coverHTML(day,true)}
async function compressCover(file){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Scegli una foto JPEG, PNG o WebP.');
 if(file.size>20*1024*1024)throw new Error('Scegli una foto inferiore a 20 MB.');
 const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Impossibile leggere la foto.'));reader.readAsDataURL(file)});
 const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('La foto non è leggibile. Esportala come JPEG.'));img.src=source});
 if(!image.naturalWidth||image.naturalWidth*image.naturalHeight>100000000)throw new Error('Questa immagine è troppo grande. Scegli una versione ridimensionata.');
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');if(!ctx)throw new Error('Questo browser non riesce a elaborare la foto.');
 let ratio=Math.min(1,1200/Math.max(image.naturalWidth,image.naturalHeight)),quality=.8;
 for(let attempt=0;attempt<12;attempt++){canvas.width=Math.max(1,Math.round(image.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(image.naturalHeight*ratio));ctx.fillStyle='#f8f3e8';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const encoded=canvas.toDataURL('image/jpeg',quality);if(encoded.length<=120000)return encoded;if(quality>.5)quality-=.15;else ratio*=.8}
 throw new Error('La foto è troppo pesante. Prova con un’altra immagine.');
}
fields.addEventListener('input',event=>{if(event.target.id==='f-coverSource'){coverFileTask++;document.querySelector('#cover-data').value='';document.querySelector('#cover-file').value='';document.querySelector('#cover-file-status').textContent='La foto verrà caricata dal collegamento inserito.';document.querySelector('#edit-form button[type="submit"]').disabled=false;const source=coverSource(event.target.value.trim());previewCover(source)}});
fields.addEventListener('change',async event=>{
 if(event.target.id!=='cover-file'||!editing||window.JAPAN_PROGRAM_SHARED?.busy)return;
 const file=event.target.files?.[0];if(!file)return;const task=++coverFileTask,button=document.querySelector('#edit-form button[type="submit"]'),status=document.querySelector('#cover-file-status');button.disabled=true;status.textContent='Preparazione della foto…';
 try{const data=await compressCover(file);if(task!==coverFileTask||!dialog.open)return;document.querySelector('#cover-data').value=data;document.querySelector('#f-coverSource').value='';fields.querySelector('[name="coverReset"]').checked=false;previewCover(data);status.textContent='Foto pronta. Salva e poi pubblica per mostrarla al gruppo.'}catch(error){if(task===coverFileTask)status.textContent=error.message}
 finally{if(task===coverFileTask)button.disabled=false}
});
function timelineState(day,clock=japanClock()){
 const timed=day.events.filter(e=>e.time),latest=timed.filter(e=>e.time<=clock.time).reduce((time,e)=>e.time>time?e.time:time,'');
 const states=Object.create(null);
 for(const e of day.events)states[e.id]=!e.time?'free':day.date<clock.date?'past':day.date>clock.date?'future':e.time===latest?'current':e.time<clock.time?'past':'future';
 return {today:day.date===clock.date,states,time:clock.time};
}
function timelineProgress(day,clock,anchors){
 if(day.date!==clock.date||!anchors.length)return null;
 const toMinutes=t=>Number(t.slice(0,2))*60+Number(t.slice(3,5));
 const now=toMinutes(clock.time)+(clock.seconds||0)/60,points=anchors.filter(p=>/^([01]\d|2[0-3]):[0-5]\d$/.test(p.time)&&Number.isFinite(p.y)).sort((a,b)=>a.time.localeCompare(b.time)),unique=[];
 for(const point of points)if(!unique.length||unique.at(-1).time!==point.time)unique.push(point);
 if(!unique.length)return null;
 if(now<=toMinutes(unique[0].time))return unique[0].y;
 for(let i=1;i<unique.length;i++){const p=unique[i-1],n=unique[i],from=toMinutes(p.time),to=toMinutes(n.time);if(now<=to)return p.y+(n.y-p.y)*(now-from)/(to-from)}
 return unique.at(-1).y
}
function updateTimeline(){
 const now=new Date(),clock=japanClock(now);clock.seconds=now.getUTCSeconds();
 for(const timeline of main.querySelectorAll('[data-timeline-date]')){
  const day=model.days.find(d=>d.id===timeline.dataset.timelineId);if(!day)continue;const state=timelineState(day,clock),rows=[...timeline.querySelectorAll('[data-event]')];
  for(const row of rows){
   const phase=state.states[row.dataset.event];row.classList.toggle('is-past',phase==='past');row.classList.toggle('is-current',phase==='current');row.classList.toggle('is-future',phase==='future');
   if(phase==='current')row.setAttribute('aria-current','step');else row.removeAttribute('aria-current');
   let badge=row.querySelector('.current-step');if(phase==='current'&&row.querySelector('.event-status')){if(!badge){badge=document.createElement('span');badge.className='current-step';row.querySelector('.event-status').append(badge)}badge.textContent='Ora nel programma'}else badge?.remove()
  }
  let marker=timeline.querySelector('.timeline-now');if(marker){marker.remove()} // Replace the former in-flow clock marker.
  let mascot=timeline.querySelector('.timeline-mascot');
  if(!state.today||timeline.dataset.timelinePast){mascot?.remove();continue}
  const box=timeline.getBoundingClientRect(),anchors=rows.map(row=>{const r=row.getBoundingClientRect(),time=row.querySelector('.event-time');const dot=time?window.getComputedStyle?.(time,'::after'):null,offset=time?(parseFloat(dot?.top)||25)+(parseFloat(dot?.height)||10)/2:Math.min((r.height||24)/2,16);return {time:row.dataset.time,y:r.top-box.top+offset}}),position=timelineProgress(day,clock,anchors);
  if(position==null){mascot?.remove();continue}
  if(!mascot){mascot=document.createElement('div');mascot.className='timeline-mascot';mascot.innerHTML='<img src="mascotte-kitsu.svg?v=20261004-giornate" width="32" height="40" alt="" aria-hidden="true"><span class="mascot-clock"></span>';mascot.setAttribute('role','img');timeline.append(mascot)}
  mascot.setAttribute('aria-label','Kitsu indica dove siamo nel programma: '+clock.time+', ora del Giappone.');mascot.title='Kitsu · '+clock.time+' in Giappone';mascot.querySelector('.mascot-clock').textContent=clock.time;
  mascot.style.transform='translateY('+Math.max(0,position-43)+'px)'
 }
}

document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateTimeline()});
window.addEventListener('resize',()=>requestAnimationFrame(updateTimeline));
main.addEventListener('toggle',()=>requestAnimationFrame(updateTimeline),true);
if(typeof ResizeObserver==='function'){const timelineObserver=new ResizeObserver(()=>requestAnimationFrame(updateTimeline));timelineObserver.observe(main)}
setInterval(()=>{if(!document.hidden)updateTimeline()},15000);

