function importPlaceHours(){
 const day=model.days.find(d=>d.id===fields.querySelector('#f-dayId')?.value);if(!day)throw Error('Seleziona la giornata del programma.');
 const parsed=window.JAPAN_PLACES.parseHours(fields.querySelector('#f-place_paste').value,day.date);
 for(const [k,value] of Object.entries(parsed)){const control=fields.querySelector('#f-place_'+k);if(!control)continue;if(['closed','open24'].includes(k))control.checked=value;else control.value=value}
 fields.querySelector('#f-place_checkedAt').value=japanClock().date;
 fields.querySelector('#f-place_sourceUrl').value=placeGoogleLink();
 fields.querySelector('#place-import-status').textContent='Orari importati per '+window.JAPAN_PLACES.dateLabel(day.date)+'. Controllali, poi salva e pubblica per tutti.'
}

